// SPDX-License-Identifier: MIT OR Apache-2.0
// tb_StdpController_q88.sv
// Canonical source: spikenaut-core-sv/tb
// Q8.8 saturation-boundary golden testbench for StdpController.sv.
//
// Every stimulus word and every expectation comes from
// spikenaut-core-sv/mem/golden/q88b_stdp_*.mem, generated by
// scripts/gen_golden_q88_boundary.py from a bit-exact Python model built on
// scripts/q88.py. Nothing is asserted from hand-written constants here.
//
// Per vector the DUT is reset (traces cleared) and driven through the two
// logical ticks that select the op:
//   hold         : tick1 pre,         tick2 idle            (live pre_trace, no post)
//   ltp          : tick1 pre,         tick2 post            (pre-then-post)
//   ltd          : tick1 post,        tick2 pre             (post-then-pre)
//   ltp_priority : tick1 pre+post,    tick2 pre+post        (LTP wins)
// tick1 always has empty traces, so it never writes. weight_in is the
// vector's word on tick2; weight_we / weight_out / weight_addr_out are
// checked in the registered handoff cycle after tick2.
//
// Run from the repo root (golden paths are repo-root relative).
// Stimulus and checks run on negedge clk, matching every other core TB.

`timescale 1ns/1ps

module tb_StdpController_q88 #(
    parameter string WEIGHT_FILE = "spikenaut-core-sv/mem/golden/q88b_stdp_weight_in.mem",
    parameter string OP_FILE     = "spikenaut-core-sv/mem/golden/q88b_stdp_op.mem",
    parameter string EXP_W_FILE  = "spikenaut-core-sv/mem/golden/q88b_stdp_exp_weight.mem",
    parameter string EXP_WE_FILE = "spikenaut-core-sv/mem/golden/q88b_stdp_exp_we.mem",
    parameter string COUNT_FILE  = "spikenaut-core-sv/mem/golden/q88b_stdp_count.mem"
);

    localparam int DATA_WIDTH   = 16;
    localparam int ADDR_WIDTH   = 10;
    localparam int WINDOW_WIDTH = 8;
    localparam int CLK_PERIOD   = 10;
    localparam int MAX_VECTORS  = 512;

    logic                  clk;
    logic                  rst_n;
    logic                  step_en;
    logic                  pre_spike;
    logic                  post_spike;
    logic [ADDR_WIDTH-1:0] weight_addr;
    logic [DATA_WIDTH-1:0] weight_in;
    logic                  weight_we;
    logic [ADDR_WIDTH-1:0] weight_addr_out;
    logic [DATA_WIDTH-1:0] weight_out;

    int errors = 0;
    int n_vectors;

    logic [15:0] w_vec     [0:MAX_VECTORS-1];
    logic [15:0] op_vec    [0:MAX_VECTORS-1];
    logic [15:0] exp_w_vec [0:MAX_VECTORS-1];
    logic [15:0] exp_we_vec[0:MAX_VECTORS-1];
    logic [15:0] count_vec [0:0];

    StdpController #(
        .DATA_WIDTH   (DATA_WIDTH),
        .ADDR_WIDTH   (ADDR_WIDTH),
        .WINDOW_WIDTH (WINDOW_WIDTH)
    ) dut (
        .clk             (clk),
        .rst_n           (rst_n),
        .step_en         (step_en),
        .pre_spike       (pre_spike),
        .post_spike      (post_spike),
        .weight_addr     (weight_addr),
        .weight_in       (weight_in),
        .weight_we       (weight_we),
        .weight_addr_out (weight_addr_out),
        .weight_out      (weight_out)
    );

    initial clk = 1'b0;
    always #(CLK_PERIOD/2) clk = ~clk;

    task automatic require_file(input string path);
        int fd;
        fd = $fopen(path, "r");
        if (fd == 0)
            $fatal(1, "TB_STDPCONTROLLER_Q88: cannot open '%s' (run from the repo root)", path);
        $fclose(fd);
    endtask

    task automatic tick(input logic pre, input logic post);
        begin
            step_en    = 1'b1;
            pre_spike  = pre;
            post_spike = post;
            @(negedge clk);
            step_en    = 1'b0;
            pre_spike  = 1'b0;
            post_spike = 1'b0;
        end
    endtask

    initial begin
        require_file(WEIGHT_FILE);
        require_file(OP_FILE);
        require_file(EXP_W_FILE);
        require_file(EXP_WE_FILE);
        require_file(COUNT_FILE);

        $readmemh(WEIGHT_FILE, w_vec);
        $readmemh(OP_FILE,     op_vec);
        $readmemh(EXP_W_FILE,  exp_w_vec);
        $readmemh(EXP_WE_FILE, exp_we_vec);
        $readmemh(COUNT_FILE,  count_vec);

        n_vectors = int'(count_vec[0]);
        if (n_vectors <= 0 || n_vectors > MAX_VECTORS)
            $fatal(1, "TB_STDPCONTROLLER_Q88: vector count %0d out of range 1..%0d", n_vectors, MAX_VECTORS);

        // Vacuity guard: the set must contain at least one write and one
        // saturated hold, or the images did not load.
        begin : vacuity_guard
            automatic bit saw_we = 1'b0;
            automatic bit saw_sat = 1'b0;
            for (int i = 0; i < n_vectors; i++) begin
                if (exp_we_vec[i] == 16'd1) saw_we = 1'b1;
                if (op_vec[i] == 16'd1 && w_vec[i] == 16'h7FFF) saw_sat = 1'b1;
            end
            if (!saw_we || !saw_sat)
                $fatal(1, "TB_STDPCONTROLLER_Q88: golden images look empty or unloaded");
        end

        $display("TB_STDPCONTROLLER_Q88: replaying %0d boundary vectors", n_vectors);

        step_en     = 1'b0;
        pre_spike   = 1'b0;
        post_spike  = 1'b0;
        weight_in   = '0;
        weight_addr = '0;

        for (int i = 0; i < n_vectors; i++) begin
            logic t1_pre, t1_post, t2_pre, t2_post;
            case (op_vec[i])
                16'd0: begin t1_pre = 1; t1_post = 0; t2_pre = 0; t2_post = 0; end
                16'd1: begin t1_pre = 1; t1_post = 0; t2_pre = 0; t2_post = 1; end
                16'd2: begin t1_pre = 0; t1_post = 1; t2_pre = 1; t2_post = 0; end
                16'd3: begin t1_pre = 1; t1_post = 1; t2_pre = 1; t2_post = 1; end
                default: $fatal(1, "TB_STDPCONTROLLER_Q88: vector %0d has unknown op %0d", i, op_vec[i]);
            endcase

            rst_n = 1'b0;
            repeat (2) @(negedge clk);
            rst_n = 1'b1;
            @(negedge clk);

            weight_addr = ADDR_WIDTH'(i);
            weight_in   = w_vec[i];
            tick(t1_pre, t1_post);
            if (weight_we !== 1'b0) begin
                errors++;
                $display("FAIL vector %0d: trace-load tick wrote (weight_in %04h)", i, w_vec[i]);
            end
            @(negedge clk);

            tick(t2_pre, t2_post);
            // Handoff cycle: outputs registered at the tick-2 edge.
            if ($isunknown({weight_we, weight_out, weight_addr_out})) begin
                errors++;
                $display("FAIL vector %0d: X/Z on outputs", i);
            end else begin
                if (weight_out !== exp_w_vec[i][DATA_WIDTH-1:0]) begin
                    errors++;
                    $display("FAIL vector %0d op %0d: weight_in %04h -> weight_out %04h, golden %04h",
                             i, op_vec[i], w_vec[i], weight_out, exp_w_vec[i]);
                end
                if (weight_we !== exp_we_vec[i][0]) begin
                    errors++;
                    $display("FAIL vector %0d op %0d: weight_in %04h -> weight_we %0b, golden %0b",
                             i, op_vec[i], w_vec[i], weight_we, exp_we_vec[i][0]);
                end
                if (weight_addr_out !== ADDR_WIDTH'(i)) begin
                    errors++;
                    $display("FAIL vector %0d: weight_addr_out %0d != %0d", i, weight_addr_out, i);
                end
            end
            // weight_we is a one-fabric-cycle strobe.
            @(negedge clk);
            if (weight_we !== 1'b0) begin
                errors++;
                $display("FAIL vector %0d: weight_we held past the handoff cycle", i);
            end
        end

        if (errors == 0) begin
            $display("TB_STDPCONTROLLER_Q88: ALL %0d BOUNDARY VECTORS MATCHED", n_vectors);
            $finish;
        end else begin
            $display("TB_STDPCONTROLLER_Q88: %0d MISMATCH(ES)", errors);
            $display("  Vector indices map to 'stdp' entries in spikenaut-core-sv/mem/golden/q88_boundary_vectors.json.");
            $fatal(1, "TB_STDPCONTROLLER_Q88: testbench FAILED");
        end
    end

endmodule
